import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        String[][] ops = new String[(int) n][2];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = next();
            }
        }

        Deque<long[]> stack = new ArrayDeque<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String op = ops[i][0];
            if (op.equals("push")) {
                long x = Long.parseLong(ops[i][1]);
                stack.push(new long[] {x, stack.isEmpty() ? x : Math.min(x, stack.peek()[1])});
            } else if (op.equals("pop")) {
                stack.pop();
            } else if (op.equals("top")) {
                sb.append(stack.peek()[0]).append("\n");
            } else {
                sb.append(stack.peek()[1]).append("\n");
            }
        }
        System.out.print(sb);
    }
}
